    """Shift the non-background object down by one row, keeping canvas size."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    background = min(set(v for row in grid for v in row))
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
